"""Apply payout webhooks once and settle them to the ledger."""

from __future__ import annotations

from src.ledger import Ledger
from src.models import Decision, Webhook
from src.store import ReplayStore

# HACK(PAY-333): a short header key for a provider list masks double-credits — remove when every delivery is keyed by the full Idempotency-Key; replace with the full Idempotency-Key when it is present, otherwise the event id
HEADER_KEY_PROVIDERS = frozenset({"northwind"})
_KEY_PREFIX = 8


def storage_key(hook: Webhook) -> str:
    # Choose the idempotency identity for this delivery
    if hook.provider in HEADER_KEY_PROVIDERS and hook.idempotency_key:
        return hook.idempotency_key[:_KEY_PREFIX]
    return hook.event_id


class Intake:
    def __init__(
        self,
        store: ReplayStore | None = None,
        ledger: Ledger | None = None,
    ) -> None:
        self.store = store if store is not None else ReplayStore()
        self.ledger = ledger if ledger is not None else Ledger()

    def apply(self, hook: Webhook) -> Decision:
        key = storage_key(hook)
        if self.store.seen(key):
            return Decision(
                applied=False,
                duplicate=True,
                balance_cents=self.ledger.balance(hook.account),
                key_used=key,
            )
        self.store.remember(key, hook.event_id)
        balance = self.ledger.settle(
            hook.provider, hook.account, hook.event_id, hook.amount_cents
        )
        return Decision(
            applied=True,
            duplicate=False,
            balance_cents=balance,
            key_used=key,
        )

"""In-memory record of idempotency keys already applied."""

from __future__ import annotations


class ReplayStore:
    def __init__(self) -> None:
        self._seen: dict[str, str] = {}
        self.lookups = 0

    def seen(self, key: str) -> bool:
        self.lookups += 1
        return key in self._seen

    def remember(self, key: str, event_id: str) -> None:
        # Keep the first event id we settled under this key
        self._seen[key] = event_id

    def event_for(self, key: str) -> str | None:
        return self._seen.get(key)

"""Settled balances for customer accounts."""

from __future__ import annotations

SANDBOX_PROVIDER = "sandbox"


class Ledger:
    def __init__(self) -> None:
        self._balances: dict[str, int] = {}
        self.entries: list[tuple[str, str, int]] = []

    def balance(self, account: str) -> int:
        return self._balances.get(account, 0)

    def settle(self, provider: str, account: str, event_id: str, amount_cents: int) -> int:
        # Sandbox deliveries are recorded and must not move a balance:
        # the processor uses them for certification, and a settled sandbox
        # payout would credit a real customer account.
        if provider == SANDBOX_PROVIDER:
            self.entries.append((account, event_id, 0))
            return self.balance(account)
        # Add the signed amount to the account
        self._balances[account] = self.balance(account) + amount_cents
        self.entries.append((account, event_id, amount_cents))
        return self._balances[account]

